#!/usr/bin/env python3
"""Unit / contract / adversarial tests for scripts/deepseek_web_login.py.

Run: python3 -m unittest scripts/test_deepseek_web_login.py -v
No network access: HTTP is injected through a fake transport.
"""

from __future__ import annotations

import base64
import json
import os
import stat
import sys
import tempfile
import unittest
from pathlib import Path
from unittest import mock

sys.path.insert(0, str(Path(__file__).resolve().parent))

import deepseek_web_login as login  # noqa: E402

# Golden vectors generated by the official PoW worker (wave-9):
# challenge = H23(salt + "_" + expireAt + "_" + i), i == expected.
GOLDEN_VECTORS = [
    ("s000", 1729666800000, 8, 3, "98ba09594cfd94513beeccb58fc56795f2a95e7285aafb58792bd8a2a69d329a"),
    ("web_001", 42, 64, 33, "026ec70203ee31dfc22c92b6e1eacf738906c606490fd59313373c26ba536dcc"),
    ("µñîçø∂e", 7, 32, 12, "8aff1c9ff6edcc7ba6132131e24ba445e053abe87f428adfdd1ced8d9b35735d"),
]


def _challenge(salt: str, expire_at: int, difficulty: int, target: str) -> dict:
    return {
        "algorithm": "DeepSeekHashV1",
        "salt": salt,
        "expire_at": expire_at,
        "signature": "sig",
        "difficulty": difficulty,
        "challenge": target,
    }


class PowTests(unittest.TestCase):
    def test_golden_vectors(self):
        for salt, expire_at, difficulty, expected, target in GOLDEN_VECTORS:
            with self.subTest(salt=salt):
                challenge = _challenge(salt, expire_at, difficulty, target)
                answer, _elapsed = login.solve_pow(challenge)
                self.assertEqual(answer, expected)

    def test_no_solution_is_explicit_error(self):
        challenge = _challenge("salt", 1, 32, "00" * 32)
        with self.assertRaises(login.LoginError) as ctx:
            login.solve_pow(challenge)
        self.assertEqual(ctx.exception.exit_code, login.EXIT_POW)

    def test_hash_is_not_standard_sha3(self):
        # 23-round Keccak must differ from SHA3-256; guards accidental "simplification".
        import hashlib

        self.assertNotEqual(login.pow_hash23(b"abc"), hashlib.sha3_256(b"abc").hexdigest())


class EncryptionTests(unittest.TestCase):
    def test_roundtrip_with_generated_keypair(self):
        from cryptography.hazmat.primitives import hashes, serialization
        from cryptography.hazmat.primitives.asymmetric import padding, rsa
        from cryptography.hazmat.primitives.ciphers import Cipher, algorithms, modes

        private_key = rsa.generate_private_key(public_exponent=65537, key_size=2048)
        spki = private_key.public_key().public_bytes(
            serialization.Encoding.DER,
            serialization.PublicFormat.SubjectPublicKeyInfo,
        )
        payload = {"region": "CN", "locale": "zh_CN", "sms_verification_code": "123456"}
        body, wrapped_b64 = login.encrypt_body(payload, base64.b64encode(spki).decode())

        wrapped = base64.b64decode(wrapped_b64)
        self.assertEqual(len(wrapped), 256)  # RSA-2048 ciphertext
        self.assertEqual(len(body) % 16, 0)

        key_iv = private_key.decrypt(
            wrapped,
            padding.OAEP(mgf=padding.MGF1(hashes.SHA256()), algorithm=hashes.SHA256(), label=None),
        )
        self.assertEqual(len(key_iv), 32)
        key, iv = key_iv[:16], key_iv[16:]
        decryptor = Cipher(algorithms.AES(key), modes.CBC(iv)).decryptor()
        plain = decryptor.update(body) + decryptor.finalize()
        pad = plain[-1]
        plain = plain[:-pad]
        self.assertEqual(json.loads(plain), payload)


class ParseTests(unittest.TestCase):
    def test_success(self):
        payload = {"code": 0, "data": {"biz_code": 1, "biz_msg": "", "biz_data": {
            "user": {"id": "u1", "token": "tok-123"}}}}
        result = login.parse_login_payload(payload)
        self.assertEqual(result.token, "tok-123")
        self.assertEqual(result.user_id, "u1")
        self.assertEqual(result.biz_code, 1)

    def test_missing_token_is_protocol_error(self):
        payload = {"code": 0, "data": {"biz_code": 0, "biz_msg": "", "biz_data": {"user": {"id": "u1"}}}}
        with self.assertRaises(login.LoginError) as ctx:
            login.parse_login_payload(payload)
        self.assertEqual(ctx.exception.exit_code, login.EXIT_PROTOCOL)

    def test_biz_code_mapping(self):
        cases = {
            login.BIZ_SMS_EXPIRED: login.EXIT_SMS_INVALID,
            login.BIZ_SMS_MISMATCH: login.EXIT_SMS_INVALID,
            login.BIZ_TOO_MANY_ATTEMPTS: login.EXIT_TOO_MANY,
            login.BIZ_RISK_DEVICE: login.EXIT_RISK_DEVICE,
            login.BIZ_BANNED: login.EXIT_BANNED,
            login.BIZ_MAINLAND_ONLY: login.EXIT_MAINLAND_ONLY,
            login.BIZ_DISABLED: login.EXIT_DISABLED,
        }
        for biz_code, exit_code in cases.items():
            with self.subTest(biz_code=biz_code):
                payload = {"code": 0, "data": {"biz_code": biz_code, "biz_msg": "x", "biz_data": None}}
                with self.assertRaises(login.LoginError) as ctx:
                    login.parse_login_payload(payload)
                self.assertEqual(ctx.exception.exit_code, exit_code)
                self.assertEqual(ctx.exception.biz_code, biz_code)

    def test_malformed_envelope(self):
        with self.assertRaises(login.LoginError) as ctx:
            login.parse_login_payload({"code": 0})
        self.assertEqual(ctx.exception.exit_code, login.EXIT_PROTOCOL)


class DeviceIdTests(unittest.TestCase):
    def test_persist_and_reuse(self):
        with tempfile.TemporaryDirectory() as tmp:
            path = Path(tmp) / "state" / "device-id"
            first = login.load_or_create_device_id(path)
            second = login.load_or_create_device_id(path)
            self.assertEqual(first, second)
            self.assertEqual(stat.S_IMODE(os.stat(path).st_mode), 0o600)

    def test_unwritable_path_falls_back(self):
        with tempfile.TemporaryDirectory() as tmp:
            path = Path(tmp) / "missing-dir" / "device-id"
            path.parent.mkdir()
            path.parent.chmod(0o500)
            try:
                value = login.load_or_create_device_id(path)
                self.assertRegex(value, r"^[0-9a-f-]{36}$")
            finally:
                path.parent.chmod(0o700)


FAKE_CHALLENGE = {
    "algorithm": "DeepSeekHashV1",
    "salt": "s000",
    "signature": "sig",
    "difficulty": 8,
    "expire_at": 1729666800000,
    "challenge": "98ba09594cfd94513beeccb58fc56795f2a95e7285aafb58792bd8a2a69d329a",
}


def _envelope(biz_code: int, biz_msg: str = "", user: dict | None = None) -> str:
    return json.dumps({"code": 0, "msg": "", "data": {
        "biz_code": biz_code, "biz_msg": biz_msg, "biz_data": {"user": user} if user else None}})


class FakeTransport:
    def __init__(self, responses):
        self.responses = list(responses)
        self.calls = []

    def __call__(self, method, path, body, extra):
        self.calls.append((method, path, body, extra))
        item = self.responses.pop(0)
        if isinstance(item, Exception):
            raise item
        return item


class ClientTests(unittest.TestCase):
    def _challenge_response(self):
        return (200, json.dumps({"code": 0, "data": {"biz_code": 0, "biz_data": {
            "guest_challenge": FAKE_CHALLENGE}}}))

    def test_login_success(self):
        transport = FakeTransport([self._challenge_response(), (200, _envelope(1, user={"id": "u1", "token": "tok"}))])
        client = login.DeepSeekWebLogin(transport=transport, device_id="dev-1")
        result = client.login("15538643833", "123456")
        self.assertEqual(result.token, "tok")
        self.assertEqual(result.user_id, "u1")
        self.assertEqual(len(transport.calls), 2)
        # Two headers must reach the login request.
        _method, _path, body, extra = transport.calls[1]
        self.assertIn("x-request-encryption-key", extra)
        self.assertIn("X-DS-Guest-PoW-Response", extra)
        self.assertGreater(len(body), 0)

    def test_login_sms_expired_maps_exit_code(self):
        transport = FakeTransport([self._challenge_response(), (200, _envelope(login.BIZ_SMS_EXPIRED))])
        client = login.DeepSeekWebLogin(transport=transport, device_id="dev-1")
        with self.assertRaises(login.LoginError) as ctx:
            client.login("15538643833", "000000")
        self.assertEqual(ctx.exception.exit_code, login.EXIT_SMS_INVALID)

    def test_network_timeout_is_explicit(self):
        transport = FakeTransport([TimeoutError("simulated timeout")])
        client = login.DeepSeekWebLogin(transport=transport, device_id="dev-1")
        with self.assertRaises(login.LoginError) as ctx:
            client.login("15538643833", "123456")
        self.assertEqual(ctx.exception.exit_code, login.EXIT_NETWORK)

    def test_oversized_garbage_response(self):
        transport = FakeTransport([(200, "x" * 100_000)])
        client = login.DeepSeekWebLogin(transport=transport, device_id="dev-1")
        with self.assertRaises(login.LoginError) as ctx:
            client.login("15538643833", "123456")
        self.assertEqual(ctx.exception.exit_code, login.EXIT_PROTOCOL)

    def test_http_500_on_login(self):
        transport = FakeTransport([self._challenge_response(), (500, "boom")])
        client = login.DeepSeekWebLogin(transport=transport, device_id="dev-1")
        with self.assertRaises(login.LoginError) as ctx:
            client.login("15538643833", "123456")
        self.assertEqual(ctx.exception.exit_code, login.EXIT_NETWORK)

    def test_verify_token_success_and_failure(self):
        good = (200, json.dumps({"code": 0, "data": {"biz_code": 0, "biz_data": {
            "chat_session": {"id": "session-1"}}}}))
        transport = FakeTransport([good])
        client = login.DeepSeekWebLogin(transport=transport, device_id="dev-1")
        self.assertEqual(client.verify_token("tok"), "session-1")

        transport = FakeTransport([(200, json.dumps({"code": 40003, "msg": "INVALID_TOKEN", "data": None}))])
        client = login.DeepSeekWebLogin(transport=transport, device_id="dev-1")
        with self.assertRaises(login.LoginError) as ctx:
            client.verify_token("tok")
        self.assertEqual(ctx.exception.biz_code, 40003)
        self.assertEqual(ctx.exception.exit_code, login.EXIT_AUTH_INVALID)


class AccountStatusTests(unittest.TestCase):
    def _status_response(self, is_muted: bool, mute_until: float = 0.0):
        return (200, json.dumps({"code": 0, "data": {"biz_code": 0, "biz_data": {
            "id": "u1", "status": 0,
            "chat": {"is_muted": 1 if is_muted else 0, "mute_until": mute_until},
        }}}))

    def test_muted_account(self):
        transport = FakeTransport([self._status_response(True, 1792971042.355)])
        client = login.DeepSeekWebLogin(transport=transport, device_id="dev-1")
        account = client.get_account_status("tok")
        self.assertTrue(account.is_muted)
        self.assertAlmostEqual(account.mute_until, 1792971042.355)
        self.assertEqual(transport.calls[0][0], "GET")
        self.assertEqual(transport.calls[0][1], "/api/v0/users/current")

    def test_unmuted_account(self):
        transport = FakeTransport([self._status_response(False)])
        client = login.DeepSeekWebLogin(transport=transport, device_id="dev-1")
        self.assertFalse(client.get_account_status("tok").is_muted)

    def test_invalid_token_is_auth_error(self):
        transport = FakeTransport([(200, json.dumps({"code": 40003, "msg": "INVALID_TOKEN", "data": None}))])
        client = login.DeepSeekWebLogin(transport=transport, device_id="dev-1")
        with self.assertRaises(login.LoginError) as ctx:
            client.get_account_status("tok")
        self.assertEqual(ctx.exception.exit_code, login.EXIT_AUTH_INVALID)

    def test_malformed_status(self):
        transport = FakeTransport([(200, json.dumps({"code": 0, "data": {"biz_code": 0}}))])
        client = login.DeepSeekWebLogin(transport=transport, device_id="dev-1")
        with self.assertRaises(login.LoginError) as ctx:
            client.get_account_status("tok")
        self.assertEqual(ctx.exception.exit_code, login.EXIT_PROTOCOL)


class CliTests(unittest.TestCase):
    def test_json_success_path(self):
        result = login.LoginResult(token="tok-json", user_id="u1", biz_code=1, biz_msg="")
        with mock.patch.object(login, "DeepSeekWebLogin") as client_cls, \
                mock.patch("builtins.print") as printer:
            client = client_cls.return_value
            client.login.return_value = result
            client.get_account_status.return_value = login.AccountStatus(False, 0.0, 0)
            client.verify_token.return_value = "session-1"
            exit_code = login.main([
                "--mobile", "15538643833", "--sms-code", "123456",
                "--json", "--verify", "--device-id", "dev-1", "--quiet",
            ])
        self.assertEqual(exit_code, login.EXIT_OK)
        payload = json.loads(printer.call_args[0][0])
        self.assertEqual(payload["token"], "tok-json")
        self.assertEqual(payload["session_id"], "session-1")

    def test_error_path_returns_mapped_exit_code(self):
        with mock.patch.object(login, "DeepSeekWebLogin") as client_cls:
            client = client_cls.return_value
            client.login.side_effect = login.LoginError("expired", exit_code=login.EXIT_SMS_INVALID, biz_code=7)
            exit_code = login.main([
                "--mobile", "15538643833", "--sms-code", "123456",
                "--device-id", "dev-1", "--quiet", "--json",
            ])
        self.assertEqual(exit_code, login.EXIT_SMS_INVALID)

    def test_verify_muted_account_exits_14(self):
        result = login.LoginResult(token="tok-muted", user_id="u1", biz_code=1, biz_msg="")
        with mock.patch.object(login, "DeepSeekWebLogin") as client_cls:
            client = client_cls.return_value
            client.login.return_value = result
            client.get_account_status.return_value = login.AccountStatus(True, 1792971042.355, 0)
            exit_code = login.main([
                "--mobile", "15538643833", "--sms-code", "123456",
                "--device-id", "dev-1", "--quiet", "--verify",
            ])
        self.assertEqual(exit_code, login.EXIT_MUTED)
        client.verify_token.assert_not_called()

    def test_status_mode_with_token_file(self):
        with tempfile.TemporaryDirectory() as tmp, \
                mock.patch.object(login, "DeepSeekWebLogin") as client_cls:
            token_file = Path(tmp) / "token.txt"
            token_file.write_text("tok\n", encoding="utf-8")
            client_cls.return_value.get_account_status.return_value = login.AccountStatus(False, 0.0, 0)
            exit_code = login.main(["--status", "--token-file", str(token_file), "--quiet", "--json"])
            self.assertEqual(exit_code, login.EXIT_OK)

    def test_invalid_sms_code_rejected_before_network(self):
        with mock.patch.object(login, "DeepSeekWebLogin") as client_cls:
            exit_code = login.main(["--mobile", "15538643833", "--sms-code", "12ab", "--quiet"])
        self.assertEqual(exit_code, login.EXIT_GENERIC)
        client_cls.assert_not_called()

    def test_out_file_is_0600(self):
        result = login.LoginResult(token="secret-token-value", user_id="u1", biz_code=0, biz_msg="")
        with tempfile.TemporaryDirectory() as tmp, \
                mock.patch.object(login, "DeepSeekWebLogin") as client_cls:
            client_cls.return_value.login.return_value = result
            out = Path(tmp) / "token.txt"
            exit_code = login.main([
                "--mobile", "15538643833", "--sms-code", "123456",
                "--device-id", "dev-1", "--quiet", "--out", str(out),
            ])
            self.assertEqual(exit_code, login.EXIT_OK)
            self.assertEqual(out.read_text(encoding="utf-8").strip(), "secret-token-value")
            self.assertEqual(stat.S_IMODE(os.stat(out).st_mode), 0o600)


if __name__ == "__main__":
    unittest.main(verbosity=2)
